test('development import bounds actual bytes and rejects twenty unrelated handoffs',async()=>{
 const id='a'.repeat(64);let reads=0;
 await assert.rejects(api.readDevelopmentReturn({name:'large.json',size:65537,arrayBuffer:async()=>{reads++;return Buffer.alloc(0);}},id),/65,536|65536/);assert.equal(reads,0);
 await assert.rejects(api.readDevelopmentReturn({name:'growing.json',size:1,arrayBuffer:async()=>Buffer.alloc(65537)},id),/65,536|65536/);
 for(let i=0;i<20;i++){const other=crypto.randomUUID().replaceAll('-','').padEnd(64,'0');const bytes=Buffer.from(JSON.stringify({handoff_id:other}));await assert.rejects(api.readDevelopmentReturn({name:'receipt.json',size:bytes.length,arrayBuffer:async()=>bytes},id),/different handoff/);}
});

