 const gateway=api.setupSettingsPayload(settings,{...base,copilot:true,db2:gatewayChoices({mcp_port:9001})});assert.equal(gateway.settings.db2_metadata_url,'http://127.0.0.1:9001/mcp');assert.equal(settings.db2_metadata_url,' https://approved.example/mcp ');
 assert.equal(api.setupSettingsPayload(settings,{...base,db2:db2Choices()}).settings.db2_metadata_url,null);
