test('Db2 saved choices round trip exact defaults and edits suppress stale saved readiness',()=>{
 const model=workstation({saved:true,readiness:{status:'READY_FOR_INTAKE',remaining:[]},settings:workstationSettings({db2_metadata_url:'http://127.0.0.1:9001/mcp'}),connection_setup:connectionSetup({choices:connectionChoices({copilot:true,db2:gatewayChoices({mcp_port:9001,row_limit:17,driver:'DB2COPY2'})}),status:'ACTION_REQUIRED',remaining:[{id:'db2_credentials',message:'Enter credentials privately in the interactive server prompt.'}]})});
 const draft=api.setupConnectionDraft(model);assert.equal(draft.db2.mcp_port,'9001');assert.equal(draft.db2.row_limit,'17');assert.equal(draft.db2.driver,'DB2COPY2');assert.equal(api.setupDraftDirty(model.settings,draft,model),false);
 for(const field of ['driver','database','certificate_file','row_limit'])assert.equal(api.setupDraftDirty(model.settings,{...draft,db2:{...draft.db2,[field]:'changed'}},model),true);
 const html=renderWorkstation(model);assert.match(html,/Intake settings saved/);assert.match(html,/Enter credentials privately/);assert.doesNotMatch(html,/Setup is done|Connectivity verified|Authentication verified/);
 const unavailable=renderWorkstation(model,{disabled:true});for(const id of ['setup-db2-mode','setup-db2-host','setup-db2-port','setup-db2-driver','setup-db2-certificate'])assert.match(unavailable,new RegExp('id="'+id+'"[^>]*disabled=""'));assert.doesNotMatch(unavailable,/Add a process/);
});
test('legacy workstation models preserve exact payload bytes without an added Db2 object',()=>{
 for(const model of [workstation(),workstation({connection_setup:connectionSetup()})]){
  const draft=api.setupConnectionDraft(model);assert.equal(Object.hasOwn(draft,'db2'),false);assert.equal(Object.hasOwn(api.setupConnectionPayload(draft),'db2'),false);
  assert.deepEqual(api.setupSettingsPayload(model.settings),{settings:model.settings});assert.equal(api.setupSettingsPayload(model.settings,api.setupConnectionPayload(draft)).settings.db2_metadata_url,null);
 }
 const legacy=workstation({settings:workstationSettings({db2_metadata_url:'https://approved.example/mcp'}),connection_setup:connectionSetup()});assert.equal(api.setupSettingsPayload(legacy.settings,api.setupConnectionPayload(api.setupConnectionDraft(legacy))).settings.db2_metadata_url,'https://approved.example/mcp');
});
